# -*- coding: utf-8 -*-
"""清理 XUnity 自动生成的翻译文件：去掉早期跑飞的条目，保留可用译文。可反复执行。"""
import os, re, json, shutil

GAME = r"C:\Users\yourname\Desktop\game！\ss\示例游戏"
OUT = os.path.join(GAME, "AutoTranslator", "Translation", "zh", "Text",
                   "_AutoGeneratedTranslations.txt")

# 已知错的条目：删掉，交给术语表/模型重新生成
DROP_KEYS = {"ゲームスタート", "クレジット", "示例游戏", "設定", "終了", "OK"}
FIX = {"Language Settings\\n言語設定": "语言设置"}

lines = []
if os.path.exists(OUT):
    shutil.copy2(OUT, OUT + ".bak")
    for raw in open(OUT, encoding="utf-8-sig").read().splitlines():
        if not raw.strip() or "=" not in raw:
            continue
        k, v = raw.split("=", 1)
        if k in DROP_KEYS:
            continue
        if k in FIX:
            v = FIX[k]
        if v in ("OK", "") or (re.search(r"^[\u3040-\u30ff]", v)):
            continue
        lines.append(f"{k}={v}")

open(OUT, "w", encoding="utf-8").write("\n".join(lines) + "\n")
print(f"kept {len(lines)} entries -> {OUT}")
print("\n".join(lines))
